SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'NEK1';

SELECT VAR_id 
FROM varInfo 
WHERE gene_name = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'D';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT AVG(AF) 
FROM varInfo 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF 
FROM varInfo 
WHERE Synonymous + ModerateImpact + HighImpact = 1;

SELECT AVG(AF) 
FROM varInfo 
